    @Test("Lossless decode is bit-exact (predictor 1 = left)")
    func losslessPredictor1() throws {
        let img = try JLIDecoder().decode(from: Self.llP1)
        #expect(img.width == Self.w && img.height == Self.h)
        #expect(img.pixelFormat == .uint8 && img.colorModel == .grayscale)
        #expect(img.data == Self.src, "predictor-1 lossless decode not bit-exact")
    }

    @Test("Lossless decode is bit-exact (predictor 7 = (left+above)/2)")
    func losslessPredictor7() throws {
        let img = try JLIDecoder().decode(from: Self.llP7)
        #expect(img.width == Self.w && img.height == Self.h)
        #expect(img.data == Self.src, "predictor-7 lossless decode not bit-exact")
    }
